/**
 * A high-performance generic object pool to prevent GC pressure.
 * Essential for projectiles, particles, and alien entities.
 */
export class Pool {
  constructor(factory, resetFn) {
    this._factory = factory; // Function to create a new instance
    this._resetFn = resetFn;   // Function to reset an instance to its initial state
    this._pool = [];          // Array of available objects
  }

  /**
   * Retrieves an object from the pool or creates a new one if empty.
   * @returns {any} An object ready for use.
   */
  acquire(...args) {
    const obj = this._pool.length > 0 ? this._pool.pop() : this._factory(...args);
    if (this._resetFn) {
      this._resetFn(obj, ...args);
    }
    return obj;
  }

  /**
   * Returns an object to the pool for future reuse.
   * @param {any} obj The object to release.
   */
  release(obj) {
    this._pool.push(obj);
  }

  /**
   * Returns the current number of available objects in the pool.
   */
  get size() {
    return this._pool.length;
  }

  /**
   * Clears the pool and allows for garbage collection.
   */
  dispose() {
    this._pool = [];
  }
}
