/**
 * Centralized registry to track Three.js disposables.
 * Ensures no Geometries, Materials, or Textures are leaked.
 */
export class MemoryManager {
  constructor() {
    this._disposables = new Set();
  }

  /**
   * Registers a Three.js object for tracking.
   * @param {THREE.Object3D|THREE.BufferGeometry|THREE.Material|THREE.Texture} object 
   */
  track(object) {
    if (!object) return;
    this._disposables.add(object);
  }

  /**
   * Disposes of all tracked objects and clears the registry.
   */
  disposeAll() {
    for (const obj of this._disposables) {
      if (obj.dispose) {
        obj.dispose();
      } else if (obj.geometry && obj.geometry.dispose) {
        obj.geometry.dispose();
      }
      // Note: Materials and Textures are often nested in meshes, 
      // but we track them explicitly if they are passed here.
    }
    this._disposables.clear();
  }

  /**
   * Removes a specific object from tracking (e.g., after manual disposal).
   */
  untrack(object) {
    this._disposables.delete(object);
  }
}

export const memoryManager = new MemoryManager();
