/**
 * Unified Dual-Input controller supporting Keyboard and Gamepad API.
 */
export class InputManager {
  constructor() {
    this.keys = new Set();
    this.gamepad = null;

    // Bindings
    this._setupKeyboard();
    this._setupGamepad();
  }

  _setupKeyboard() {
    window.addEventListener('keydown', (e) => this.keys.add(e.code));
    window.addEventListener('keyup', (e) => this.keys.delete(e.code));
  }

  _setupGamepad() {
    window.addEventListener("gamepadconnected", (e) => {
      console.log("Gamepad connected:", e.gamepad.id);
      this.gamepad = e.gamepad;
    });
    window.addEventListener("gamepaddisconnected", () => {
      this.gamepad = null;
    });
  }

  /**
   * Checks if a specific key is currently pressed.
   * @param {string} keyCode - e.g., 'KeyW', 'ArrowLeft'
   */
  isKeyPressed(keyCode) {
    return this.keys.has(keyCode);
  }

  /**
   * Checks if the primary action button (e.g., Space or Gamepad Button 0) is pressed.
   */
  isActionPressed() {
    // Keyboard check
    if (this.keys.has('Space') || this.keys.has('KeyZ')) return true;

    // Gamepad check
    if (this.gamepad) {
      const buttons = this.gamepad.buttons;
      if (buttons[0].pressed) return true; // 'A' or 'X' button
    }

    return false;
  }

  /**
   * Gets the horizontal axis value (-1 to 1).
   */
  getHorizontalAxis() {
    // Keyboard check
    if (this.keys.has('ArrowLeft') || this.keys.has('KeyA')) return -1;
    if (this.keys.has('ArrowRight') || this.keys.has('KeyD')) return 1;

    // Gamepad check
    if (this.gamepad) {
      const axes = this.gamepad.axes;
      if (Math.abs(axes[0]) > 0.1) return axes[0]; // Left stick X-axis
    }

    return 0;
  }
}
