/**
 * The core Game Loop and Time Management system.
 * Handles timeScale for Hit-Stop effects and the main RAF loop.
 */
export class Engine {
  constructor() {
    this.lastTime = 0;
    this.deltaTime = 0;
    this.timeScale = 1.0; // Used for Hit-Stop (e.g., set to 0.05)
    this.isRunning = false;
    this.onUpdate = null; // Callback: (dt) => {}
  }

  /**
   * Starts the game loop.
   */
  start() {
    if (this.isRunning) return;
    this.isRunning = true;
    this.lastTime = performance.now();
    requestAnimationFrame(this._loop.bind(this));
  }

  /**
   * Stops the game loop.
   */
  stop() {
    this.isRunning = false;
  }

  /**
   * Internal RAF loop.
   */
  _loop(currentTime) {
    if (!this.isRunning) return;

    const rawDelta = (currentTime - this.lastTime) / 1000; // Convert to seconds
    this.lastTime = currentTime;

    // Apply timeScale for slow-motion/hit-stop effects
    this.deltaTime = rawDelta * this.timeScale;

    if (this.onUpdate) {
      this.onUpdate(this.deltaTime);
    }

    requestAnimationFrame(this._loop.bind(this));
  }

  /**
   * Triggers a brief frame freeze (Hit-Stop).
   * @param {number} duration - Duration in seconds.
   */
  async triggerHitStop(duration) {
    const originalScale = this.timeScale;
    this.timeScale = 0.05; // Slow motion

    await new Promise(resolve => setTimeout(resolve, duration * 1000));

    this.timeScale = originalScale;
  }
}
